def isNumber(s):
    n = len(s)
    i = 0
    if i < n and (s[i] == '+' or s[i] == '-'):
        i += 1
    before = 0
    while i < n and '0' <= s[i] <= '9':
        i += 1
        before += 1
    after = 0
    if i < n and s[i] == '.':
        i += 1
        while i < n and '0' <= s[i] <= '9':
            i += 1
            after += 1
    if before + after == 0:
        return False
    if i < n and (s[i] == 'e' or s[i] == 'E'):
        i += 1
        if i < n and (s[i] == '+' or s[i] == '-'):
            i += 1
        digits = 0
        while i < n and '0' <= s[i] <= '9':
            i += 1
            digits += 1
        if digits == 0:
            return False
    return i == n
